import { describe, expect, it } from "vitest";
import { handleStripeWebhook } from "../../src/payments/stripe-webhook";

const sign = (body: string) =>
  `t=1,v1=${createHmac("sha256", "whsec_demo").update(`1.${body}`).digest("hex")}`;

